@page "/board"
@namespace sv_38552eaf239b4fc582387a762ffb680e.Components.Pages.Board
@using sv_38552eaf239b4fc582387a762ffb680e.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (isLoading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Tasks="allTasks" />
    <TaskSearch SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="(id) => MoveTask(id, "In Progress")"
                      OnTaskCreated="(m) => CreateTask(m, "To Do")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="(id) => MoveTask(id, "To Do")"
                      OnMoveRight="(id) => MoveTask(id, "Done")"
                      OnTaskCreated="(m) => CreateTask(m, "In Progress")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="GetFilteredTasks("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="(id) => MoveTask(id, "In Progress")"
                      OnTaskCreated="(m) => CreateTask(m, "Done")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task CreateTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    font-weight: 600;
}

.stat-overdue {
    color: #dc3545;
}

.task-search {
    margin-bottom: 1rem;
}

.task-search input {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 1rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

.column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    min-height: 100px;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem 0;
    color: #6c757d;
    font-size: 0.85rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: #fff;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #6c757d;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.column-footer {
    margin-top: 0.75rem;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 4px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: #fff;
    padding: 0.75rem;
    border-radius: 6px;
    border: 1px solid #dee2e6;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.4rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading {
    color: #6c757d;
    font-style: italic;
}

.error {
    color: #dc3545;
    font-weight: 600;
}

