.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    font-weight: 600;
}

.stat-overdue {
    color: #dc3545;
}

.task-search {
    margin-bottom: 1rem;
}

.task-search input {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 1rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

.column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    min-height: 100px;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem 0;
    color: #6c757d;
    font-size: 0.85rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: #fff;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #6c757d;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.column-footer {
    margin-top: 0.75rem;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 4px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: #fff;
    padding: 0.75rem;
    border-radius: 6px;
    border: 1px solid #dee2e6;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.75rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.4rem 0.75rem;
    background: #6c757d;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading {
    color: #6c757d;
    font-style: italic;
}

.error {
    color: #dc3545;
    font-weight: 600;
}

